import React, { useEffect, useState } from 'react';
import './PaymentSuccessModal.css';

function PaymentSuccessModal({ isVisible, onComplete }) {
  const [countdown, setCountdown] = useState(10);

  useEffect(() => {
    if (!isVisible) return;
    
    const timer = setInterval(() => {
      setCountdown(prev => {
        if (prev <= 1) {
          clearInterval(timer);
          onComplete();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [isVisible, onComplete]);

  if (!isVisible) return null;

  return (
    <div className="payment-success-modal">
      <div className="modal-content">
        <div className="success-icon">✓</div>
        <h2>Paiement Validé !</h2>
        <p>Votre paiement a été confirmé avec succès.</p>
        <p>Vous allez être redirigé vers la page de tests et d'analyse dans <strong>{countdown}</strong> secondes...</p>
        <div className="loading-bar">
          <div className="loading-progress" style={{width: `${(10-countdown)/10*100}%`}}></div>
        </div>
      </div>
    </div>
  );
}

export default PaymentSuccessModal;
